     * Replaces the current history entry rather than pushing one, so that filtering does
     * not fill the browser history.
     *
     * <p>The browser's own {@code history.replaceState} is called directly, rather than
     * through Vaadin's {@code History}: Vaadin parses the URL and re-encodes the query, which
     * would turn the comma in {@code status=ACTIVE,CLOSED} into {@code %2C}. The URL is
     * written as {@code ./} plus the query, because an empty URL would keep whatever query
     * the browser already has.
     */
    private void writeUrl(CustomerFilter filter) {
        String query = toQueryString(filter);
        String url = query.isEmpty() ? "./" : "./?" + query;
        getUI().ifPresent(ui -> ui.getPage().executeJs(
                "window.history.replaceState(window.history.state, '', $0)", url));
