+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+import java.util.function.Predicate;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1000, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JARNO = new Customer(
+            1009, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            1035, "Joséphine", "Aaltonen", "josefine@example.com", "Portugal", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        Predicate<Customer> matcher = filter.matcher();
+        return matcher.test(customer);
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    @Test
+    void anEmptyFilterMatchesEveryone() {
+        assertTrue(matches(CustomerFilter.EMPTY, ADA));
+        assertTrue(matches(name(""), JARNO));
+        assertTrue(matches(name("   "), JOSEPHINE));
+    }
+
+    @Test
+    void everyTermMustMatchTheFirstOrLastName() {
+        assertTrue(matches(name("ada aal"), ADA));
+        assertTrue(matches(name("aal ada"), ADA));
+        assertFalse(matches(name("ada virtanen"), ADA));
+        assertFalse(matches(name("bruno aal"), ADA));
+    }
+
+    @Test
+    void whitespaceIsNotSignificant() {
+        assertTrue(matches(name("  ada \t  aal  "), ADA));
+        assertTrue(matches(name("ada aal"), ADA));
+    }
+
+    @Test
+    void matchingIgnoresCase() {
+        assertTrue(matches(name("ADA"), ADA));
+        assertTrue(matches(name("aaltonen"), ADA));
+    }
+
+    @Test
+    void matchingIgnoresAccentsInBothDirections() {
+        assertTrue(matches(name("makinen"), JARNO));
+        assertTrue(matches(name("MAKINEN"), JARNO));
+        assertTrue(matches(name("mäkinen"), JARNO));
+        assertTrue(matches(name("josephine"), JOSEPHINE));
+        assertTrue(matches(name("Joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void matchingIsBySubstring() {
+        assertTrue(matches(name("ltonen"), ADA));
+        assertTrue(matches(name("ad"), ADA));
+    }
+
+    @Test
+    void aNameMatchAlsoNeedsAMatchingStatus() {
+        assertTrue(matches(new CustomerFilter("ada", Set.of(CustomerStatus.ACTIVE)), ADA));
+        assertFalse(matches(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)), ADA));
+    }
+
+    @Test
+    void anEmptyStatusSetKeepsEveryStatus() {
+        for (CustomerStatus status : CustomerStatus.values()) {
+            Customer customer = new Customer(1, "A", "B", "a@b", "C", status);
+            assertTrue(matches(new CustomerFilter("", Set.of()), customer));
+        }
+    }
+
+    @Test
+    void aStatusSetKeepsOnlyThoseStatuses() {
+        CustomerFilter activeOrClosed = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertTrue(matches(activeOrClosed, ADA));
+        assertTrue(matches(activeOrClosed, JOSEPHINE));
+        assertFalse(matches(new CustomerFilter("", Set.of(CustomerStatus.PENDING)), ADA));
+    }
+
+    @Test
+    void bothCriteriaMustHold() {
+        CustomerFilter adaClosed = new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED));
+        assertFalse(matches(adaClosed, ADA));
+        assertTrue(matches(new CustomerFilter("josephine", Set.of(CustomerStatus.CLOSED)), JOSEPHINE));
+    }
+}
